const cutoff = Date.now() - 24*60*60*1000;
const items = $input.all()
  .map(i => i.json)
  .filter(j => new Date(j.pubDate || j.isoDate || 0).getTime() > cutoff)
  .slice(0, 15)
  .map(j => ({ title: j.title, link: j.link, snippet: (j.contentSnippet || '').slice(0, 200) }));
return [{ json: { stories: items } }];
